"""Write matlab/uav_params.m from params/aerosonde.py so MATLAB/Simulink use exactly the same numbers.

Run: python scripts/export_matlab_params.py
"""
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from params import aerosonde as P  # noqa: E402


def main():
    names = [n for n in dir(P) if not n.startswith("_") and isinstance(getattr(P, n), (int, float))]
    lines = [
        "function P = uav_params()",
        "%UAV_PARAMS  Aerosonde parameters (SI). GENERATED by scripts/export_matlab_params.py from params/aerosonde.py.",
        "%   Do not edit by hand. Sources/caveats: see params/aerosonde.py.",
        "%#codegen",
    ]
    for n in names:
        lines.append(f"P.{n} = {float(getattr(P, n))!r};")
    lines.append("end")
    out = ROOT / "matlab" / "uav_params.m"
    out.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(f"wrote {out} ({len(names)} parameters)")


if __name__ == "__main__":
    main()
